with transactions_by_account as (select account_id, max(txn_time) as latest_txn_time from transactions where merchant in ('Grab', 'Lazada', 'Amazon') group by account_id) select accounts.id, accounts.account_type, accounts.customer_id, transactions_by_account.latest_txn_time from accounts left join transactions_by_account on accounts.id = transactions_by_account.account_id order by account_type
